/// <summary>
/// PaffH 22.11.21
/// Helper for dirPartyTable
/// </summary>
public class NDXDirPartyTableHelper
{
    DirPartyTable dirPartyTable;

}

Method.Source:
/// <summary>
/// PaffH 22.11.21
/// </summary>
/// <param name = "_dirPartyTable">DirPartyTable</param>
protected void new(DirPartyTable _dirPartyTable)
{
    dirPartyTable = _dirPartyTable;
}

/// <summary>
/// PaffH 22.11.21
/// </summary>
/// <param name = "_dirPartyTable">DirPartyTable</param>
/// <returns>NDXDirPartyTableHelper</returns>
static public NDXDirPartyTableHelper construct(DirPartyTable _dirPartyTable)
{
    return new NDXDirPartyTableHelper(_dirPartyTable);
}

/// <summary>
/// PaffH 23.11.21
/// </summary>
/// <returns>primary LogisticsPostalAddress from dirPartyTable.PrimaryAddressLocation</returns>
public LogisticsPostalAddress LogisticsPostalAddressFromPrimaryAddressLocation()
{
    Query q;
    QueryBuildDataSource qbds1;
    QueryRun qr;
    LogisticsPostalAddress logisticsPostalAddress;
    if (!dirPartyTable.PrimaryAddressLocation)
    {
        return null;
    }

    q = new Query();
    qbds1 = q.addDataSource(tableNum(LogisticsPostalAddress));
    qbds1.firstOnly(true);
    qbds1.addRange(fieldNum(LogisticsPostalAddress, Location)).value(queryValue(dirPartyTable.PrimaryAddressLocation));
    qbds1.addOrderByField(fieldNum(LogisticsPostalAddress, ValidTo), SortOrder::Descending);

    qr = new QueryRun(q);
    qr.next();
    logisticsPostalAddress = qr.get(tableNum(LogisticsPostalAddress));
    return logisticsPostalAddress;
}

/// <summary>
/// PaffH 22.11.21
/// get actual postalAddress from primary address
/// </summary>
/// <returns>LogisticsPostalAddress</returns>
public LogisticsPostalAddress LogisticsPostalAddressPrimary()
{
    Query q = new Query();
    QueryBuildDataSource qbds1 = q.addDataSource(tableNum(LogisticsPostalAddress));
    qbds1.firstOnly(true);
    qbds1.addOrderByField(fieldNum(LogisticsPostalAddress, ValidTo), SortOrder::Descending);

    QueryBuildDataSource qbds2 = qbds1.addDataSource(tableNum(LogisticsLocation));
    qbds2.relations(true);
    qbds2.joinMode(JoinMode::ExistsJoin);

    QueryBuildDataSource qbds3 = qbds2.addDataSource(tableNum(DirPartyLocation));
    qbds3.relations(true);
    qbds3.joinMode(JoinMode::ExistsJoin);
    qbds3.addRange(fieldNum(DirPartyLocation, Party)).value(queryValue(dirPartyTable.RecId));
    qbds3.addRange(fieldNum(DirPartyLocation, IsPrimary)).value(queryValue(NoYes::Yes));

    QueryRun qr = new QueryRun(q);
    qr.next();
    return (qr.get(tableNum(LogisticsPostalAddress)) as LogisticsPostalAddress);
}
